    head=re.sub(r'<title>.*?</title>',f'<title>{title}</title>',head)
    head=re.sub(r'(<link rel="stylesheet" href="/motion\.css[^"]*">)',r'\1<link rel="stylesheet" href="/scenes.css">',head)
    head=re.sub(r'(<script src="/motion\.js[^"]*" defer></script>)',r'\1<script src="/scenes.js" defer></script>',head)
    head=head.replace('</head>','<link rel="stylesheet" href="/scene-reference.css"></head>')
    head=head.replace('<a class="active" href="/">HOME</a>','<a href="/">HOME</a>')
    tail=suffix
    for part in ['about','slabs','how-it-works','field-notes','faq','home','chapters']:
        head=head.replace(f'href="#{part}"',f'href="/#{part}"')
        tail=tail.replace(f'href="#{part}"',f'href="/#{part}"')
    (root/'dist'/f'{name}.html').write_text(head+'<main id="main" class="scene-main">'+body+'</main>\n'+tail)
    print('Prepared',name+'.html')
